function GoogleSignIn({ onCredential }) {
  const mount = React.useRef(null)
  useEffect(() => {
    if (!GOOGLE_CLIENT_ID || !mount.current) return
    const render = () => {
      if (!window.google?.accounts?.id || !mount.current) return
      window.google.accounts.id.initialize({ client_id: GOOGLE_CLIENT_ID, callback: response => onCredential(response.credential) })
      window.google.accounts.id.renderButton(mount.current, { theme: 'outline', size: 'large', shape: 'rectangular', text: 'continue_with', width: Math.min(390, mount.current.parentElement?.clientWidth || 390), logo_alignment: 'left' })
    }
    if (window.google?.accounts?.id) render()
    else {
      const script = document.createElement('script'); script.src = 'https://accounts.google.com/gsi/client'; script.async = true; script.defer = true; script.onload = render; document.head.appendChild(script)
    }
  }, [onCredential])
  if (!GOOGLE_CLIENT_ID) return null
  return <div className="google-wrap"><div ref={mount}/></div>
}

